export default function SignupPage() {
  return (
    <div className="min-h-screen bg-[#0a0a0b] text-white flex items-center justify-center px-4">
      <div className="w-full max-w-md rounded-[14px] border border-white/10 bg-[#0d0d0e]/60 p-6">
        <h1 className="text-xl font-semibold mb-2">Create your Sylor account</h1>
        <p className="text-sm text-white/40 mb-6">
          In your real app this will redirect to onboarding → pricing → setup.
        </p>
        <form className="space-y-4">
          <div>
            <label className="text-sm text-white/70 mb-1 block">Email</label>
            <input
              type="email"
              className="w-full rounded-[10px] bg-black/20 border border-white/10 px-3 py-2 text-sm outline-none focus:border-purple-400"
              placeholder="you@example.com"
            />
          </div>
          <div>
            <label className="text-sm text-white/70 mb-1 block">Password</label>
            <input
              type="password"
              className="w-full rounded-[10px] bg-black/20 border border-white/10 px-3 py-2 text-sm outline-none focus:border-purple-400"
              placeholder="••••••••"
            />
          </div>
          <button
            type="submit"
            className="w-full rounded-[10px] bg-white text-black py-2 text-sm font-medium hover:bg-white/90"
          >
            Continue
          </button>
        </form>
        <p className="text-xs text-white/30 mt-4">
          Tip: change all CTAs to `/pricing` once Stripe is fully wired.
        </p>
      </div>
    </div>
  );
}
